{
  "schemaVersion": "laidies-newsstand-source-evidence.v1",
  "candidateId": "openai-agent-australia-medicare-20260924",
  "sources": [
    {
      "id": "australian-pm",
      "url": "https://www.pm.gov.au/media/press-conference-new-york",
      "authority": "Australian government primary transcript",
      "passages": [
        "This incident occurred in June of this year and involved an OpenAI agent gaining unauthorised access into the public-facing Medicare statistics reporting service portal.",
        "The Medicare Statistics Reporting Portal is a public-facing statistics portal that contains non-sensitive Medicare information relating to data and statistics such as spending. No personal information is believed to have been accessed at this stage, but investigations are ongoing.",
        "The agent accessed public and non-public files.",
        "it took until 10 September before there was any notification at all."
      ],
      "limit": "Government account is current but investigation is ongoing."
    },
    {
      "id": "transluce",
      "url": "https://transluce.org/agent-activity",
      "authority": "Independent research organisation report",
      "passages": [
        "The agents also tried on three occasions to hack public data providers, including an Australian government website.",
        "We note that the extent of the observed activity is minor, attempting a low number of probe payloads and we observe no evidence of exploitation.",
        "Overall, the evidence is consistent with, but does not prove, that the agents may have learned this behavior over one or more training runs."
      ],
      "limit": "Public artifact analysis is incomplete and does not establish full activity or causation."
    },
    {
      "id": "bleepingcomputer",
      "url": "https://www.bleepingcomputer.com/news/security/openai-hacked-australian-medicare-govt-site-probed-data-providers/",
      "authority": "Independent reporting with attributed OpenAI spokesperson quote",
      "passages": [
        "initial review suggests that much of the activity described in Transluce’s report overlaps with cases at varying stages of investigation in our ongoing review of misaligned model activity.",
        "Our review found no evidence of patient records being accessed. The information accessed included aggregate health statistics and internal file names."
      ],
      "limit": "This is a reported spokesperson quote, not a direct OpenAI incident statement."
    }
  ]
}
